import React, { useState } from 'react';
import axios from 'axios';

const ExamDataCount = ({ franchiseId }) => {
    const [period, setPeriod] = useState('month'); // Default period
    const [examDataCount, setExamDataCount] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    // Function to fetch exam data count
    const fetchExamDataCount = async () => {
        setLoading(true);
        setError('');
        try {
            const response = await axios.get(`/franchises/${franchiseId}/exam-data/count`, {
                params: { period }
            });
            setExamDataCount(response.data.count);  // Set the count from API response
        } catch (err) {
            setError('An error occurred while fetching data.');
        } finally {
            setLoading(false);
        }
    };

    // Handler for period change
    const handlePeriodChange = (e) => {
        setPeriod(e.target.value);
    };

    return (
        <div>
            <h2>Exam Data Count for Franchise {franchiseId}</h2>

            <div>
                <label htmlFor="period">Select Period: </label>
                <select id="period" value={period} onChange={handlePeriodChange}>
                    <option value="month">This Month</option>
                    <option value="week">This Week</option>
                    <option value="day">Today</option>
                </select>
            </div>

            <button onClick={fetchExamDataCount} disabled={loading}>
                {loading ? 'Loading...' : 'Get Exam Data Count'}
            </button>

            {error && <p style={{ color: 'red' }}>{error}</p>}

            {examDataCount !== null && !loading && (
                <div>
                    <h3>Exam Data Count: {examDataCount}</h3>
                </div>
            )}
        </div>
    );
};

export default ExamDataCount;
